	public class CheckSecurityCode : ISecurityCode
	{
		public static string[] Sitenames
		{
			get
			{
				string sites = Sunplus.Agent.Configurations.AppSettings.Configuration.Get("EnableSecurityVerify");
				if (!string.IsNullOrEmpty(sites))
				{
					return sites.Split(new char[] { ',' }, StringSplitOptions.RemoveEmptyEntries);
				}

				return new string[] { };
			}
		}

		public void RegisterSC(IUserSession userSession)
		{
			SecurityCodeBO bo = new SecurityCodeBO(userSession.NetSessionId);
			bo.GenerateSecurityToken();
		}

		public ErrorType RequiredSecurityCode(HttpRequest request, IUserSession userSession, out string errMsg)
		{
            errMsg = string.Empty;

            // Internal - do not need to check SC
            if (userSession.IsInternal)
            {
                return ErrorType.Success;
            }
	
			/// pre-condition:
			/// 1. action
			/// 2. UserPermission.IsShowSecurityVerify
			/// 3. first time logon
            var url = request.RawUrl.Split(new char[]{ '?' })[0].ToLower();
            string enable = SecurityCodeUrl.Configuration.Get(url);
			if (enable != "1"
				|| !UserPermission.IsShowSecurityVerify
				|| !userSession.IsLogged)
			{
				return ErrorType.Success;
			}

			/// check SC
			string secCode = request["inputSecCode"];
			if (!string.IsNullOrEmpty(secCode)) // has SC in Request
			{
				bool isSessionSaving = true;
				string chkNotAskAgain = request["chkNotAskAgain"];
				if (!string.IsNullOrEmpty(chkNotAskAgain))
				{
					isSessionSaving = string.Equals(chkNotAskAgain, "true", StringComparison.OrdinalIgnoreCase);
				}

				AuthorizationBO bo = new AuthorizationBO(userSession.NetSessionId);
				int errCode = bo.CheckSecurityCode(secCode, Sunplus.Agent.Model.Common.AgentIPFormat.GetClientIP(), out errMsg, isSessionSaving);
				return (ErrorType)errCode;
			}
			else
			{
				SCResult scResult = userSession.SecurityCodeResult;
				// show SC popup to verify input SC of user
				if (scResult == SCResult.FORCED_CHANGE_SC || scResult == SCResult.PROVIDED_SC)
				{
					return ErrorType.RequiredSecurityCode;
				}
			}

			return ErrorType.Success;
		}
	}
